query:
NODE VALUE incoming_sum SumAgg<INT64> = 0
TABLE rows {id STRING, total INT64}

MATCH (src@player)-[e@follow]->(dst@player)
PER PATH {
  SET dst.@incoming_sum += coalesce(e.degree, 0)
}

MATCH (p@player)
PER NODE (p) {
  EXPORT p.id, p.@incoming_sum INTO rows
}

FOR r IN rows
RETURN r.id AS id, r.total AS total
